export function getGuidedTourCopy(language: string): TourMessages {
  const base = language.toLowerCase().split(/[-_]/)[0] as TourLanguage;
  return guidedTourMessages[base] ?? guidedTourMessages.es;
}
export function guidedTourStepCopy(language: string, id: TourStageId): { title: string; body: string } {
  const [title, body] = getGuidedTourCopy(language).stages[id];
  return { title, body };
}
